int copy_huge_page_table_entry(struct mm_struct *dst_mm, pte_t *dst_pte, struct vm_area_struct *dst_vma, unsigned long dst_addr, unsigned long src_addr, struct page **pagep) {
    struct page *page = *pagep;
    int ret = -EFAULT;

    if (!dst_mm || !dst_pte || !dst_vma || !pagep) {
        return -EINVAL;
    }

    if (!page) {
        page = alloc_pages(GFP_HIGHUSER | __GFP_ZERO, HPAGE_SHIFT - PAGE_SHIFT);
        if (!page) {
            return -ENOMEM;
        }
    }

    if (copy_from_user(page_address(page), (void __user *)src_addr, HPAGE_SIZE)) {
        goto out;
    }

    if (dst_vma->vm_flags & VM_SHARED) {
        set_page_dirty(page);
    } else {
        set_page_private(page, (unsigned long)dst_vma);
    }

    set_pte_at(dst_mm, dst_addr, dst_pte, pte_mkhuge(pte_mkyoung(pte_mkdirty(pte_mkwrite(pte_set_owner(pte_clear(pte_none(*dst_pte)), page))))));

    flush_tlb_page(dst_vma, dst_addr);

    *pagep = page;
    ret = 0;

out:
    if (ret < 0 && !(*pagep)) {
        __free_pages(page, HPAGE_SHIFT - PAGE_SHIFT);
    }
    return ret;
}
